{
  "changed": [
    {
      "change": "middleware.ts is renamed to proxy.ts, and the exported function must be renamed to proxy; the logic stays the same. middleware.ts is deprecated and will be removed in a future version.",
      "lesson": 3
    },
    {
      "change": "Synchronous access to params is removed, so a page must await params before reading params.slug. Reading it directly from props without awaiting no longer works.",
      "lesson": 4
    },
    {
      "change": "revalidateTag() now requires a cacheLife profile as its second argument, for example revalidateTag('posts', 'max'). In a Server Action that must read its own writes, use the new updateTag() instead.",
      "lesson": 5
    },
    {
      "change": "The next lint command is removed, and next build no longer runs linting. Run ESLint or Biome directly instead, or use the codemod npx @next/codemod@canary next-lint-to-eslint-cli.",
      "lesson": 7
    }
  ],
  "whatsNew": {
    "level": "intermediate",
    "offer": "Learn Cache Components, the React Compiler, and updateTag in Next.js 16 to keep your pages fast and your saved data fresh.",
    "skills": [
      {
        "description": "You set cacheComponents to true in next.config.ts so pages use Partial Pre-Rendering and use cache for instant navigation.",
        "name": "Turn on Cache Components for instant navigation"
      },
      {
        "description": "You set reactCompiler to true in next.config.ts so React adds automatic memoization to your components without manual memo calls.",
        "name": "Enable automatic memoization with the React Compiler"
      },
      {
        "description": "You call updateTag() in a Server Action so the cache expires and the same request reads the fresh data you just saved.",
        "name": "Read fresh data after a save with updateTag"
      }
    ],
    "title": "What's new in Next.js 16"
  }
}

